import tempfile,os,subprocess
code="'use strict';
const base='http://127.0.0.1:17448';
const get=async(url)=>{const x=await fetch(url,{signal:AbortSignal.timeout(4000)});if(!x.ok)throw Error('http_'+x.status);return x.json()};
const canonical=x=>{const m=String(x||'').match(/chatgpt\.com\/c\/([^/?#]+)/i);return m?m[1]:''};
async function probe(url,expression,limit=2600){
 return new Promise(resolve=>{
  let finished=false;let socket=null;
  const started=performance.now();
  const done=(result)=>{if(finished)return;finished=true;clearTimeout(timer);try{socket?.close()}catch{}resolve({ms:Math.round(performance.now()-started),...result})};
  const timer=setTimeout(()=>done({ok:false,error:'timeout'}),limit);
  try{
   socket=new WebSocket(url);
   socket.addEventListener('open',()=>{try{socket.send(JSON.stringify({id:17,method:'Runtime.evaluate',params:{expression,returnByValue:true,awaitPromise:false}}))}catch{done({ok:false,error:'send_error'})}});
   socket.addEventListener('message',e=>{try{const x=JSON.parse(e.data);if(x.id===17)done(x.error?{ok:false,error:'CDP_error'}:{ok:true,value:x.result?.result?.value??null})}catch{done({ok:false,error:'parse_error'})}});
   socket.addEventListener('error',()=>done({ok:false,error:'ws_error'}));
  }catch{done({ok:false,error:'connect_exception'})}
 })
}
async function main(){
 const [profiles,chats,watch]=await Promise.all([
  get(base+'/api/ai-profiles'),get(base+'/api/supervisor-watchdog/managed-chats?inspect=0'),get(base+'/api/supervisor-watchdog?detect=0')]);
 const list=Array.isArray(profiles.aiProfiles)?profiles.aiProfiles:[];
 const rows=Array.isArray(chats.chats)?chats.chats:[];
 const configured=watch.config?.profileId||'';
 const cache=new Map();
 async function inspect(chat){
  const profile=list.find(x=>x.id===(chat.profileId||configured))||list.find(x=>x.provider==='chatgpt');
  if(!profile?.debugPort)return {name:chat.name,error:'no_debug_port'};
  const port=Number(profile.debugPort);
  if(!cache.has(port))cache.set(port,get('http://127.0.0.1:'+port+'/json/list').catch(()=>[]));
  const targets=await cache.get(port);
  const exact=targets.find(x=>canonical(x.url)&&canonical(x.url)===canonical(chat.url));
  if(!exact?.webSocketDebuggerUrl)return {name:chat.name,error:'target_missing',targetCount:targets.length};
  const basic=await probe(exact.webSocketDebuggerUrl,'2+2');
  const nodes=basic.ok?await probe(exact.webSocketDebuggerUrl,'document.querySelectorAll("main div,main section").length'):null;
  const main=basic.ok?await probe(exact.webSocketDebuggerUrl,'(document.querySelector("main")?.innerText||"").length'):null;
  return {name:chat.name,basic,nodes,main};
 }
 const result=await Promise.all(rows.map(inspect));
 console.log(JSON.stringify({observedAt:new Date().toISOString(),diagnostic:'read_only_basic_CDP_vs_DOM',count:result.length,results:result}));
}
main().catch(e=>{console.log(JSON.stringify({error:String(e.message).slice(0,80)}));process.exitCode=1});"
